create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, role text not null default 'viewer' check(role in ('admin','editor','viewer')), created_at timestamptz not null default now());
create table if not exists public.destinations (id uuid primary key default gen_random_uuid(), name text not null, abastecido_por text not null default 'nucleo', marcas text[] not null default '{}', created_at timestamptz not null default now());
create table if not exists public.items (id uuid primary key default gen_random_uuid(), name text not null, kind text not null check(kind in ('consumible','equipamiento')), category text not null, scope text not null default 'generico' check(scope in ('marca','generico')), brand text, ocasion text, unit text not null default 'unidades', stock_nucleo integer not null default 0 check(stock_nucleo>=0), stock_sf integer not null default 0 check(stock_sf>=0), reorder_nucleo integer not null default 0 check(reorder_nucleo>=0), reorder_sf integer not null default 0 check(reorder_sf>=0), lead_time_days integer not null default 0, default_min integer not null default 3, total_qty integer not null default 0, danados integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.movements (id uuid primary key default gen_random_uuid(), item_id uuid not null references public.items(id), type text not null, qty integer not null check(qty>0), fecha date not null, origen text, destino_id uuid references public.destinations(id), lugar text, motivo text, person text, notes text, estado text, created_by uuid references auth.users(id) default auth.uid(), created_at timestamptz not null default now());
create or replace function public.register_movement(p_item_id uuid,p_type text,p_qty integer,p_fecha date,p_person text default null) returns public.movements language plpgsql security invoker as $$ declare result public.movements; begin if p_qty<=0 then raise exception 'La cantidad debe ser mayor que cero'; end if; insert into public.movements(item_id,type,qty,fecha,person) values(p_item_id,p_type,p_qty,p_fecha,p_person) returning * into result; if p_type='compra' then update public.items set stock_nucleo=stock_nucleo+p_qty where id=p_item_id; else raise exception 'Tipo de movimiento no implementado todavía'; end if; return result; end; $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.email)); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security; alter table public.destinations enable row level security; alter table public.items enable row level security; alter table public.movements enable row level security;
create policy "authenticated read profiles" on public.profiles for select to authenticated using(true); create policy "own profile insert" on public.profiles for insert to authenticated with check(auth.uid()=id);
create policy "authenticated read destinations" on public.destinations for select to authenticated using(true); create policy "authenticated manage destinations" on public.destinations for all to authenticated using(true) with check(true);
create policy "authenticated read items" on public.items for select to authenticated using(true); create policy "authenticated manage items" on public.items for all to authenticated using(true) with check(true);
create policy "authenticated read movements" on public.movements for select to authenticated using(true); create policy "authenticated insert movements" on public.movements for insert to authenticated with check(true);
alter publication supabase_realtime add table public.items; alter publication supabase_realtime add table public.movements; alter publication supabase_realtime add table public.destinations;
insert into public.destinations(name,abastecido_por,marcas) values ('Nissan','nucleo',array['Nissan']),('Kia - Rosario','nucleo',array['Kia']),('BYD Santa Fe','deposito_sf',array['BYD']),('Honda Santa Fe','deposito_sf',array['Honda']) on conflict do nothing;
